import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        // Approximate sqrt(2) with 1.41421356; using erff for single precision
        out[idx] = 0.5f * val * (1.0f + erff(val * 0.70710678f));
    }
}

torch::Tensor gelu_cuda(torch::Tensor x) {
    auto out = torch::zeros_like(x);
    int size = x.numel();
    const int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;
    gelu_kernel<<<grid_size, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
"""

gelu_cpp_source = r"torch::Tensor gelu_cuda(torch::Tensor x);"

gelu_op = load_inline(
    name="gelu_extension",
    cpp_sources=gelu_cpp_source,
    cuda_sources=gelu_cuda_source,
    functions=["gelu_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a custom GELU activation.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return gelu_op.gelu_cuda(x)

